import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../../environments/environment';

export interface DisplayValues {
	fcp_display: string;
	lcp_display: string;
	si_display: string;
	cls_display: string;
	overall_category: 'Fast' | 'Moderate' | 'Slow';
}

export interface CompareResult {
	_id?: string;
	siteA: string;
	siteB: string;
	industry?: string;
	strategy: string;
	scoresA: Record<string, number>;
	scoresB: Record<string, number>;
	displayA?: DisplayValues;
	displayB?: DisplayValues;
	reportA?: any;
	reportB?: any;
	mobileScoresA?: Record<string, number>;
	desktopScoresA?: Record<string, number>;
	mobileScoresB?: Record<string, number>;
	desktopScoresB?: Record<string, number>;
	mobileDisplayA?: DisplayValues;
	desktopDisplayA?: DisplayValues;
	mobileDisplayB?: DisplayValues;
	desktopDisplayB?: DisplayValues;
	mobileReportA?: any;
	desktopReportA?: any;
	mobileReportB?: any;
	desktopReportB?: any;
	mobileScores?: Record<string, number>;
	desktopScores?: Record<string, number>;
	mobileDisplay?: DisplayValues;
	desktopDisplay?: DisplayValues;
	mobileReport?: any;
	desktopReport?: any;
	leadSubmitted?: boolean;
}

export interface CompareHistory {
	_id: string;
	siteA: string;
	siteB: string;
	scoresA: Record<string, number>;
	scoresB: Record<string, number>;
	strategy: string;
	createdAt: string;
	leadSubmitted?: boolean;
}

export interface MetricRow {
	id: string;
	label: string;
	scoreA: number;
	scoreB: number;
	displayA?: string;
	displayB?: string;
}

@Injectable({ providedIn: 'root' })
export class WebsiteComparatorService {
	private baseUrl = `${environment.baseUrl}/api/compare`;

	constructor(private http: HttpClient) { }

	compare(siteA: string, siteB: string, strategy: string, industry?: string): Observable<CompareResult> {
		return this.http.post<CompareResult>(this.baseUrl, { siteA, siteB, strategy, industry });
	}

	submitLead(comparisonId: string, data: { leadName: string; leadBiz: string; leadWhatsapp: string; leadEmail: string; industry?: string; pdfBase64?: string; }): Observable<any> {
		return this.http.post<any>(`${this.baseUrl}/${comparisonId}/lead`, data);
	}

	getHistory(): Observable<CompareHistory[]> {
		return this.http.get<CompareHistory[]>(`${this.baseUrl}/history`);
	}
}
