    const drawWrapped = (text: string, x: number, width: number, lineHeight = 12): number => {
      const lines = doc.splitTextToSize(sanitize(text), width) as string[];
      lines.forEach((line) => {
        doc.text(line, x, y);
        y += lineHeight;
      });
      return lines.length * lineHeight;
    };

    // Auto-sizes the pill to fit its label (shrinking the font if needed to respect maxWidth)
    // so text never overlaps neighboring content or clips past the pill edges.
    const drawBadge = (label: string, x: number, badgeY: number, color: Rgb, maxWidth?: number, align: 'left' | 'right' = 'left'): number => {
      const text = label.toUpperCase();
      const padding = 18;
      let fontSize = 7.5;
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(fontSize);
      let pillWidth = doc.getTextWidth(text) + padding;
      if (maxWidth && pillWidth > maxWidth) {
        while (pillWidth > maxWidth && fontSize > 5.5) {
          fontSize -= 0.5;
          doc.setFontSize(fontSize);
          pillWidth = doc.getTextWidth(text) + padding;
        }
        pillWidth = Math.min(pillWidth, maxWidth);
      }
      const pillX = align === 'right' ? x - pillWidth : x;
      setFill(color);
      doc.roundedRect(pillX, badgeY - 11, pillWidth, 17, 8, 8, 'F');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(fontSize);
      doc.setTextColor(255, 255, 255);
      doc.text(text, pillX + pillWidth / 2, badgeY, { align: 'center' });
      return pillWidth;
    };

